using System.Text.Json;
using Json.Schema;
using Tellurian.Trains.Drawing.Model.Files;

namespace Tellurian.Trains.Drawing.Model.Tests;

/// <summary>Validates JSON against the schemas generated by <see cref="DrawingFileSchema"/>.</summary>
internal static class SchemaValidator
{
    private static readonly Dictionary<DrawingFileKind, Lazy<JsonSchema>> Schemas = DrawingFileSchema.Kinds.ToDictionary(
        k => k,
        k => new Lazy<JsonSchema>(() => JsonSchema.FromText(DrawingFileSchema.Create(k).ToJsonString(), baseUri: new($"https://schema.test/{DrawingFileSchema.FileName(k)}"))));
    private static readonly EvaluationOptions Options = new() { RequireFormatValidation = true, OutputFormat = OutputFormat.List };

    public static void AssertValid(DrawingFileKind kind, string json)
    {
        using var document = JsonDocument.Parse(json);
        var results = Schema(kind).Evaluate(document.RootElement, Options);
        if (results.IsValid) return;
        var errors = (results.Details ?? [])
            .Where(d => d.Errors is not null)
            .SelectMany(d => d.Errors!.Select(e => $"{d.InstanceLocation}: {e.Value}"));
        Assert.Fail($"The {kind} file doesn't match its schema:{Environment.NewLine}{string.Join(Environment.NewLine, errors)}");
    }

    public static bool IsValid(DrawingFileKind kind, string json)
    {
        using var document = JsonDocument.Parse(json);
        return Schema(kind).Evaluate(document.RootElement, Options).IsValid;
    }

    private static JsonSchema Schema(DrawingFileKind kind) => Schemas[kind].Value;
}
